import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;

/**
 * Variant 2: Using BufferedReader and PrintWriter directly
 */
public class Main {
    public static void main(String[] args) throws Exception {
        InputStream is = System.in;
        BufferedReader br = new BufferedReader(new InputStreamReader(is));
        PrintWriter pw = new PrintWriter(System.out);
        GTakeMetro solver = new GTakeMetro();
        solver.solve(1, br, pw);
        pw.close();
    }

    static class GTakeMetro {
        int n, m, s;
        long t;

        void step() {
            int curJump = (int) (t % n);
            int sign = s < m ? 1 : -1;
            s += sign * curJump;
            s %= n;
            if (s < 0) s += n;
            t--;
        }

        void doLoop() {
            for (int i = 0; i < n; i++) step();
        }

        public void solve(int testNumber, BufferedReader in, PrintWriter out) throws Exception {
            String[] parts = in.readLine().split(" ");
            n = Integer.parseInt(parts[0]);
            m = Integer.parseInt(parts[1]);
            s = Integer.parseInt(parts[2]) - 1;
            t = Long.parseLong(parts[3]);

            while ((t % n) != 0) step();

            long[] lastSeem = new long[n];
            Arrays.fill(lastSeem, -1);
            while (t != 0) {
                doLoop();
                if (lastSeem[s] != -1) {
                    long interval = lastSeem[s] - t;
                    t %= interval;
                    break;
                } else {
                    lastSeem[s] = t;
                }
            }
            while (t != 0) step();
            out.println(s + 1);
        }
    }
}
